-- BrainRush: wrong options for the "3 choices" helper (owner request 2026-10-23)
--
-- The "3 choices" helper shows the question as multiple choice: the correct answer (cut at
-- its first bracket, like the options) and 2 stored wrong options, shuffled. This file fills in the
-- wrong options, in English and Arabic (wrong_1, wrong_2, wrong_1_ar, wrong_2_ar), for all
-- 761 questions in the bank on 2026-10-23, in every category. The options have the same type
-- and form as the answer (a year for a year, a person for a person), are plausible but wrong,
-- and are never one of the accepted variants. Flags use countries with similar-looking flags;
-- Landmarks use similar landmarks. A question without options has the helper greyed out.
-- Review doc (one table per category, for striking options):
-- docs/question-sets/wrong-options-review.md.
--
-- Requires sql/migrate-add-wrong-options.sql (the 4 columns). Run that migration FIRST:
-- without the columns, the UPDATE stops with "Unknown column 'q.wrong_1'" and nothing is
-- changed; run the migration, then this file again. Run it on whichever database is selected
-- (there is no USE line):
--   local:   mysql -u root brainrush < sql/add-wrong-options.sql
--   hosted:  phpMyAdmin -> select the database -> Import this file
-- Run it AFTER the sql/add-*-questions.sql files, so the questions exist.
-- Rows are matched by category name + question text + image, because ids differ between the
-- local and hosted databases and every Flags row shares one prompt (the image tells them
-- apart). A seed row whose question was renamed, moved or deleted matches nothing and is
-- skipped. Questions are never added, deleted or changed: only the 4 option columns are set.
-- It is safe to run again: only empty fields (NULL or '') are filled, so options edited on
-- the admin page are kept. To replace an option, clear it on the admin page (or set it to
-- NULL) and run the file again. Check afterwards:
--   SELECT COUNT(*) FROM questions WHERE COALESCE(wrong_1, '') = '' OR COALESCE(wrong_2, '') = ''
--     OR COALESCE(wrong_1_ar, '') = '' OR COALESCE(wrong_2_ar, '') = '';

SET NAMES utf8mb4;

DROP TEMPORARY TABLE IF EXISTS wrong_options_seed;

CREATE TEMPORARY TABLE wrong_options_seed (
  category_name VARCHAR(100) NOT NULL,
  question      TEXT         NOT NULL,
  image         VARCHAR(255) NOT NULL,
  wrong_1       VARCHAR(255) NOT NULL,
  wrong_2       VARCHAR(255) NOT NULL,
  wrong_1_ar    VARCHAR(255) NOT NULL,
  wrong_2_ar    VARCHAR(255) NOT NULL
) DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_520_ci;

-- AI (42)

-- Cartoons & Childhood (24)

-- Egyptians (81)

-- Flags (53)

-- Food & Drink (37)

-- Gen Z (66)

-- Geography (75)

-- History (70)

-- Landmarks (46)

-- Movies (62)

-- Science (75)

-- Sports (62)

-- Technology (68)

UPDATE questions q
JOIN categories c ON c.id = q.category_id
JOIN wrong_options_seed s ON s.category_name = c.name AND s.question = q.question AND s.image = q.image
SET q.wrong_1    = COALESCE(NULLIF(q.wrong_1, ''), s.wrong_1),
    q.wrong_2    = COALESCE(NULLIF(q.wrong_2, ''), s.wrong_2),
    q.wrong_1_ar = COALESCE(NULLIF(q.wrong_1_ar, ''), s.wrong_1_ar),
    q.wrong_2_ar = COALESCE(NULLIF(q.wrong_2_ar, ''), s.wrong_2_ar);

DROP TEMPORARY TABLE wrong_options_seed;
