INSERT INTO wrong_options_seed (category_name, question, image, wrong_1, wrong_2, wrong_1_ar, wrong_2_ar) VALUES
('Food & Drink', 'Which popular Egyptian street dish mixes rice, macaroni and chickpeas, topped with spicy tomato sauce and crispy fried onions?', '', 'Megadara', 'Hawawshi', 'المجدرة', 'الحواوشي'),
